type Tool = 'select' | 'text' | 'edit' | 'highlight' | 'whiteout' | 'redact' | 'box' | 'draw' | 'image' | 'stamp' | 'check';
type Tab = 'edit' | 'pages' | 'form' | 'protect' | 'ocr';
interface Snap { bytes: Uint8Array; annots: Annot[] }
const STAMPS = ['DATE', 'RECEIVED', 'PAID', 'APPROVED', 'DENIED', 'COPY', 'CONFIDENTIAL', 'URGENT', 'FAXED', 'RESUBMITTED'];
const FONT_CSS: Record<FontName, string> = { Helvetica: 'Helvetica, Arial, sans-serif', Times: '"Times New Roman", Times, serif', Courier: '"Courier New", monospace' };
const MAX_BYTES = 25 * 1024 * 1024;
const blob = (b: Uint8Array) => new Blob([b as unknown as BlobPart], { type: 'application/pdf' });

// ───────── pdf.js helpers ─────────
async function loadDoc(bytes: Uint8Array) { const pdfjs = await import('pdfjs-dist'); pdfjs.GlobalWorkerOptions.workerSrc = new URL('pdfjs-dist/build/pdf.worker.min.mjs', import.meta.url).toString(); return { pdfjs, doc: await pdfjs.getDocument({ data: bytes.slice() }).promise }; }
async function textItems(pdfjs: any, doc: any, index: number): Promise<TextItem[]> {
  const pg = await doc.getPage(index + 1); const vp = pg.getViewport({ scale: 1 }); const tc = await pg.getTextContent(); const out: TextItem[] = [];
  for (const it of tc.items as any[]) { if (!it.str || !it.str.trim()) continue; const t = pdfjs.Util.transform(vp.transform, it.transform); const hgt = Math.hypot(t[2], t[3]) || it.height || 10; const wd = (it.width || 0); const ux = t[0] / (Math.hypot(t[0], t[1]) || 1), uy = t[1] / (Math.hypot(t[0], t[1]) || 1); const vx = t[2] / (hgt || 1), vy = t[3] / (hgt || 1);
    const xs = [t[4], t[4] + ux * wd, t[4] + vx * hgt, t[4] + ux * wd + vx * hgt], ys = [t[5], t[5] + uy * wd, t[5] + vy * hgt, t[5] + uy * wd + vy * hgt]; const x = Math.min(...xs), y = Math.min(...ys); out.push({ str: it.str, x, y, w: Math.max(...xs) - x, h: Math.max(...ys) - y }); }
  return out;
}
async function rasterizePage(bytes: Uint8Array, index: number): Promise<{ jpeg: Uint8Array; w: number; h: number }> {
  const { doc } = await loadDoc(bytes); const pg = await doc.getPage(index + 1); const S = 2; const vp = pg.getViewport({ scale: S }); const c = document.createElement('canvas'); c.width = Math.ceil(vp.width); c.height = Math.ceil(vp.height);
  await pg.render({ canvas: c, canvasContext: c.getContext('2d')!, viewport: vp } as any).promise; const blob: Blob = await new Promise((res, rej) => c.toBlob((b) => (b ? res(b) : rej(new Error('Could not flatten the page'))), 'image/jpeg', 0.92)); const jpeg = new Uint8Array(await blob.arrayBuffer()); c.width = c.height = 0; await (doc as any).destroy?.(); return { jpeg, w: vp.width / S, h: vp.height / S };
}

function PageCanvas({ doc, index, scale, onSize, children }: { doc: any; index: number; scale: number; onSize: (w: number, h: number) => void; children: React.ReactNode }) {
  const ref = useRef<HTMLCanvasElement>(null); const [dim, setDim] = useState({ w: 0, h: 0 }); const [err, setErr] = useState<string | null>(null);
  useEffect(() => {
    let live = true; let task: { cancel(): void } | null = null;
    (async () => { try { const pg = await doc.getPage(index + 1); if (!live) return; const vp = pg.getViewport({ scale }); const cv = ref.current!; cv.width = Math.ceil(vp.width); cv.height = Math.ceil(vp.height); setDim({ w: vp.width, h: vp.height }); onSize(vp.width / scale, vp.height / scale); const t = pg.render({ canvas: cv, canvasContext: cv.getContext('2d')!, viewport: vp }); task = t; await t.promise; setErr(null); } catch (e) { if (live && !/cancel/i.test(String(e))) setErr((e as Error).message); } })();
    return () => { live = false; task?.cancel(); };
  }, [doc, index, scale]); // eslint-disable-line react-hooks/exhaustive-deps
  return <div className="relative inline-block bg-white shadow-md" style={{ width: dim.w || undefined, height: dim.h || undefined }}>{err ? <div className="p-6 text-sm text-red-500">{err}</div> : <canvas ref={ref} />}<div className="absolute inset-0" style={{ width: dim.w, height: dim.h }}>{children}</div></div>;
}
function Thumb({ doc, index, active, checked, onClick, onCheck }: { doc: any; index: number; active: boolean; checked: boolean; onClick: () => void; onCheck: () => void }) {
  const ref = useRef<HTMLCanvasElement>(null);
  useEffect(() => { let live = true; (async () => { try { const pg = await doc.getPage(index + 1); const base = pg.getViewport({ scale: 1 }); const s = 96 / base.width; const vp = pg.getViewport({ scale: s }); const c = ref.current; if (!c || !live) return; c.width = Math.ceil(vp.width); c.height = Math.ceil(vp.height); await pg.render({ canvas: c, canvasContext: c.getContext('2d')!, viewport: vp }).promise; } catch { /* thumbnail is cosmetic */ } })(); return () => { live = false; }; }, [doc, index]);
  return <div className={'relative rounded-md p-1 cursor-pointer ' + (active ? 'ring-2 ring-brand-500 bg-brand-500/10' : 'hover:bg-white/5')} onClick={onClick}><canvas ref={ref} className="mx-auto bg-white shadow-sm max-w-full" /><div className="flex items-center justify-between text-[11px] mt-0.5 px-0.5"><span>{index + 1}</span><input type="checkbox" aria-label={`Select page ${index + 1}`} checked={checked} onClick={(e) => e.stopPropagation()} onChange={onCheck} /></div></div>;
}


/** Draw or type a signature / initials and hand it back as a transparent PNG. */
function SigPad({ onUse }: { onUse: (dataUrl: string, ar: number) => void }) {
  const ref = useRef<HTMLCanvasElement>(null); const down = useRef(false); const [typed, setTyped] = useState(''); const [empty, setEmpty] = useState(true);
  const pos = (e: React.PointerEvent) => { const r = ref.current!.getBoundingClientRect(); return [(e.clientX - r.left) * (ref.current!.width / r.width), (e.clientY - r.top) * (ref.current!.height / r.height)]; };
  const clear = () => { const c = ref.current!; c.getContext('2d')!.clearRect(0, 0, c.width, c.height); setEmpty(true); };
  const use = () => { const c = ref.current!; const x = c.getContext('2d')!; const d = x.getImageData(0, 0, c.width, c.height); let x0 = c.width, y0 = c.height, x1 = 0, y1 = 0; for (let y = 0; y < c.height; y++) for (let xx = 0; xx < c.width; xx++) if (d.data[(y * c.width + xx) * 4 + 3] > 10) { x0 = Math.min(x0, xx); x1 = Math.max(x1, xx); y0 = Math.min(y0, y); y1 = Math.max(y1, y); } if (x1 <= x0) return; const w = x1 - x0 + 8, h = y1 - y0 + 8; const o = document.createElement('canvas'); o.width = w; o.height = h; o.getContext('2d')!.drawImage(c, x0 - 4, y0 - 4, w, h, 0, 0, w, h); onUse(o.toDataURL('image/png'), w / h); };
  const type = (t: string) => { setTyped(t); const c = ref.current!; const x = c.getContext('2d')!; x.clearRect(0, 0, c.width, c.height); if (!t) return setEmpty(true); x.fillStyle = '#0f172a'; x.font = 'italic 64px "Brush Script MT", "Segoe Script", "Snell Roundhand", cursive'; x.textBaseline = 'middle'; x.fillText(t, 16, c.height / 2, c.width - 32); setEmpty(false); };
  return <div className="space-y-1.5"><canvas ref={ref} width={520} height={150} className="w-full bg-white rounded border hair touch-none" onPointerDown={(e) => { down.current = true; ref.current!.setPointerCapture(e.pointerId); const [x, y] = pos(e); const c = ref.current!.getContext('2d')!; c.strokeStyle = '#0f172a'; c.lineWidth = 3; c.lineCap = 'round'; c.lineJoin = 'round'; c.beginPath(); c.moveTo(x, y); setEmpty(false); }} onPointerMove={(e) => { if (!down.current) return; const [x, y] = pos(e); const c = ref.current!.getContext('2d')!; c.lineTo(x, y); c.stroke(); }} onPointerUp={() => { down.current = false; }} />
    <div className="flex gap-1.5 items-center"><input className="input !py-1 text-xs flex-1" placeholder="…or type your name / initials" value={typed} onChange={(e) => type(e.target.value)} /><button className="btn btn-sm" onClick={() => { setTyped(''); clear(); }}>Clear</button><button className="btn btn-primary btn-sm" disabled={empty} onClick={use}>Use</button></div></div>;
}

export default function PdfStudio({ initial, onExit, onToWord }: { initial?: { name: string; bytes: Uint8Array } | null; onExit?: () => void; onToWord?: (name: string, text: string) => void }) {
  const svc = useServices(); const st = useStore(); const nav = useNavigate(); const [q, setQ] = useState(''); const [hits, setHits] = useState<(TextHit & { page: number })[]>([]); const [claimId, setClaimId] = useState(''); const [fills, setFills] = useState<(FillSuggestion & { on: boolean })[]>([]); const [health, setHealth] = useState<Health[] | null>(null); const [name, setName] = useState(initial?.name || 'document.pdf'); const [snap, setSnap] = useState<Snap | null>(initial ? { bytes: initial.bytes, annots: [] } : null); const past = useRef<Snap[]>([]); const future = useRef<Snap[]>([]); const [, bump] = useState(0);
  const [pdf, setPdf] = useState<{ doc: any; pdfjs: any; n: number } | null>(null); const [page, setPage] = useState(0); const [zoom, setZoom] = useState(1.3); const [size, setSize] = useState({ w: 612, h: 792 }); const [items, setItems] = useState<TextItem[]>([]);
  const [tab, setTab] = useState<Tab>('edit'); const [tool, setTool] = useState<Tool>('select'); const [sel, setSel] = useState<string | null>(null); const [pages, setPages] = useState<Set<number>>(new Set()); const [busy, setBusy] = useState<string | null>(null); const [dirty, setDirty] = useState(false);
  const [style, setStyle] = useState({ font: 'Helvetica' as FontName, size: 12, color: '#111827', bold: false, italic: false }); const [stamp, setStamp] = useState('RECEIVED'); const [img, setImg] = useState<{ dataUrl: string; ar: number } | null>(null);
  const [fields, setFields] = useState<FormField[]>([]); const [vals, setVals] = useState<Record<string, string>>({}); const [phi, setPhi] = useState<(PhiHit & { page: number; on: boolean })[]>([]); const [mark, setMark] = useState({ text: 'DRAFT', opacity: 0.25 }); const [num, setNum] = useState({ template: 'Page {n} of {N}', pos: 'bc' as Pos, bates: false, prefix: '', start: 1 }); const [split, setSplit] = useState('1-2, 3-'); const [ocrText, setOcrText] = useState(''); const [ocrProg, setOcrProg] = useState<[number, number] | null>(null);
  const bytes = snap?.bytes; const annots = snap?.annots || [];
  const fileIn = useRef<HTMLInputElement>(null); const mergeIn = useRef<HTMLInputElement>(null); const imgIn = useRef<HTMLInputElement>(null); const imgPageIn = useRef<HTMLInputElement>(null); const drag = useRef<any>(null);

  // ───────── history ─────────
  const push = () => { if (!snap) return; past.current.push(snap); if (past.current.length > 25) past.current.shift(); future.current = []; };
  const change = (next: Partial<Snap>, record = true) => { if (!snap) return; if (record) push(); setSnap({ ...snap, ...next }); setDirty(true); bump((n) => n + 1); };
  const undo = () => { const p = past.current.pop(); if (!p || !snap) return; future.current.push(snap); setSnap(p); bump((n) => n + 1); };
  const redo = () => { const f = future.current.pop(); if (!f || !snap) return; past.current.push(snap); setSnap(f); bump((n) => n + 1); };
  const setAnnots = (fn: (a: Annot[]) => Annot[], record = true) => { if (!snap) return; if (record) push(); setSnap({ ...snap, annots: fn(snap.annots) }); setDirty(true); bump((n) => n + 1); };
  const guard = async <T,>(label: string, fn: () => Promise<T>): Promise<T | undefined> => { setBusy(label); try { return await fn(); } catch (e: any) { toast.err(e?.message || `${label} failed`); } finally { setBusy(null); } };

  // ───────── document loading ─────────
  useEffect(() => { if (!bytes) { setPdf(null); return; } let live = true; let cur: any = null; loadDoc(bytes).then(({ pdfjs, doc }) => { cur = doc; if (live) { setPdf({ doc, pdfjs, n: doc.numPages }); setPage((p) => Math.min(p, doc.numPages - 1)); } }).catch((e) => live && toast.err('Could not open that PDF: ' + (e?.message || e))); return () => { live = false; try { cur?.destroy?.(); } catch { /* closed */ } }; }, [bytes]);
  useEffect(() => { if (!pdf) return; let live = true; textItems(pdf.pdfjs, pdf.doc, page).then((t) => live && setItems(t)).catch(() => live && setItems([])); return () => { live = false; }; }, [pdf, page]);
  useEffect(() => { if (!bytes) return; inspectPdf(bytes).then((r) => { setFields(r.fields); setVals((v) => Object.fromEntries(r.fields.map((f) => [f.name, v[f.name] ?? '']))); }).catch(() => setFields([])); }, [bytes]);
  useEffect(() => { const h = (e: BeforeUnloadEvent) => { if (dirty) { e.preventDefault(); e.returnValue = ''; } }; window.addEventListener('beforeunload', h); return () => window.removeEventListener('beforeunload', h); }, [dirty]);
  useEffect(() => { const h = (e: KeyboardEvent) => { const tgt = e.target as HTMLElement; if (/INPUT|TEXTAREA|SELECT/.test(tgt?.tagName)) return; if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'z') { e.preventDefault(); e.shiftKey ? redo() : undo(); } else if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'y') { e.preventDefault(); redo(); } else if ((e.key === 'Delete' || e.key === 'Backspace') && sel) { e.preventDefault(); setAnnots((a) => a.filter((x) => x.id !== sel)); setSel(null); } else if (e.key === 'Escape') { setSel(null); setTool('select'); } }; window.addEventListener('keydown', h); return () => window.removeEventListener('keydown', h); });

  // ───────── open / new ─────────
  const openBytes = (n: string, b: Uint8Array) => { past.current = []; future.current = []; setName(n); setSnap({ bytes: b, annots: [] }); setPage(0); setPages(new Set()); setSel(null); setPhi([]); setOcrText(''); setDirty(false); };
  const openFile = async (f?: File | null) => { if (!f) return; if (f.size > MAX_BYTES) return toast.err('File is over 25 MB'); await guard('Opening', async () => { if (OFFICE_EXT.test(f.name)) { if (!(await probeServices()).gotenberg.up) throw new Error('Word / Excel / PowerPoint files open in the Word editor, or start the local document services (deploy/services) to convert them to PDF here.'); const pdf = await convertToPdf(f, f.name); openBytes(f.name.replace(/\.\w+$/, '') + '.pdf', pdf); toast.ok('Converted to PDF on your local server'); return; } const b = new Uint8Array(await f.arrayBuffer()); if (/^image\//.test(f.type)) openBytes(f.name.replace(/\.\w+$/, '') + '.pdf', await imagesToPdf([{ bytes: b, type: f.type }])); else { await pageInfo(b); openBytes(f.name, b); } }); };

  // ───────── baking & structural ops ─────────
  const bake = async (b = bytes!, a = annots) => applyAnnots(b, a, { rasterize: rasterizePage });
  const structural = (label: string, fn: (b: Uint8Array) => Promise<Uint8Array>) => guard(label, async () => { if (!snap) return; const baked = await bake(); const out = await fn(baked); push(); setSnap({ bytes: out, annots: [] }); setDirty(true); bump((n) => n + 1); });
  const idxs = () => (pages.size ? [...pages].sort((a, b) => a - b) : [page]);
  const download = () => guard('Preparing PDF', async () => { const out = await bake(); const hadRedact = annots.some((a) => a.kind === 'rect' && a.mode === 'redact'); downloadFile(name.replace(/\.pdf$/i, '') + '-edited.pdf', blob(out), 'application/pdf'); setDirty(false); toast.ok(hadRedact ? 'Saved. Pages with redactions were flattened to images so the hidden text is really gone.' : 'PDF saved'); });
  const printIt = () => guard('Preparing print', async () => { const out = await bake(); const url = URL.createObjectURL(blob(out)); const w = window.open(url); if (!w) toast.err('Allow pop-ups to print'); setTimeout(() => URL.revokeObjectURL(url), 60000); });

  // ───────── annotation interaction ─────────
  const pt = (e: React.PointerEvent | PointerEvent, el: HTMLElement) => { const r = el.getBoundingClientRect(); return { x: (e.clientX - r.left) / zoom, y: (e.clientY - r.top) / zoom }; };
  const hit = (p: { x: number; y: number }) => items.find((it) => p.x >= it.x - 1 && p.x <= it.x + it.w + 1 && p.y >= it.y - 1 && p.y <= it.y + it.h + 1);
  const onDown = (e: React.PointerEvent<HTMLDivElement>) => {
    if (!snap || e.button !== 0) return; const el = e.currentTarget; const p = pt(e, el);
    if (tool === 'select') { setSel(null); return; }
    if (tool === 'text') { const a: Annot = { id: newId(), page, kind: 'text', x: p.x, y: p.y - style.size * 0.4, text: 'Text', size: style.size, color: style.color, font: style.font, bold: style.bold, italic: style.italic }; setAnnots((l) => [...l, a]); setSel(a.id); setTool('select'); return; }
    if (tool === 'edit') { const it = hit(p); if (!it) return toast.info('Click directly on existing text'); const sz = Math.max(6, Math.round(it.h * 0.85 * 10) / 10); const wo: Annot = { id: newId(), page, kind: 'rect', x: it.x - 1, y: it.y - 1, w: it.w + 3, h: it.h + 2, mode: 'whiteout' }; const t: Annot = { id: newId(), page, kind: 'text', x: it.x, y: it.y + (it.h - sz) * 0.45, text: it.str, size: sz, color: '#000000', font: style.font, bold: false, italic: false }; setAnnots((l) => [...l, wo, t]); setSel(t.id); setTool('select'); return; }
    if (tool === 'check') { setAnnots((l) => [...l, { id: newId(), page, kind: 'check', x: p.x - 6, y: p.y - 7, size: 14, color: '#16a34a' }]); return; }
    if (tool === 'stamp') { setAnnots((l) => [...l, { id: newId(), page, kind: 'stamp', x: p.x, y: p.y, text: stamp === 'DATE' ? fmtDate(todayISO()) : stamp, color: /PAID|APPROVED/.test(stamp) ? '#16a34a' : /DENIED|URGENT/.test(stamp) ? '#dc2626' : '#2563eb', size: 16 }]); return; }
    if (tool === 'image') { if (!img) return toast.info('Choose a picture or signature first'); const w = 150; setAnnots((l) => [...l, { id: newId(), page, kind: 'image', x: p.x, y: p.y, w, h: w / img.ar, dataUrl: img.dataUrl }]); setTool('select'); return; }
    el.setPointerCapture(e.pointerId);
    if (tool === 'draw') { drag.current = { kind: 'draw', id: newId(), pts: [[p.x, p.y]] as [number, number][] }; push(); setSnap((s) => (s ? { ...s, annots: [...s.annots, { id: drag.current.id, page, kind: 'draw', pts: drag.current.pts, color: style.color, width: 2 }] } : s)); return; }
    drag.current = { kind: 'rect', id: newId(), x0: p.x, y0: p.y }; push(); setSnap((s) => (s ? { ...s, annots: [...s.annots, { id: drag.current.id, page, kind: 'rect', x: p.x, y: p.y, w: 1, h: 1, mode: tool as any }] } : s));
  };
  const onMove = (e: React.PointerEvent<HTMLDivElement>) => {
    const d = drag.current; if (!d) return; const p = pt(e, e.currentTarget);
    if (d.kind === 'draw') { d.pts.push([p.x, p.y]); setSnap((s) => (s ? { ...s, annots: s.annots.map((a) => (a.id === d.id && a.kind === 'draw' ? { ...a, pts: [...d.pts] } : a)) } : s)); }
    else if (d.kind === 'rect') setSnap((s) => (s ? { ...s, annots: s.annots.map((a) => (a.id === d.id && a.kind === 'rect' ? { ...a, x: Math.min(d.x0, p.x), y: Math.min(d.y0, p.y), w: Math.abs(p.x - d.x0), h: Math.abs(p.y - d.y0) } : a)) } : s));
    else if (d.kind === 'move') { const dx = p.x - d.sx, dy = p.y - d.sy; setSnap((s) => (s ? { ...s, annots: s.annots.map((a) => { if (a.id !== d.id) return a; const o = d.orig; return a.kind === 'draw' ? { ...a, pts: (o as any).pts.map(([x, y]: [number, number]) => [x + dx, y + dy]) } : { ...a, x: (o as any).x + dx, y: (o as any).y + dy }; }) } : s)); }
    else if (d.kind === 'resize') setSnap((s) => (s ? { ...s, annots: s.annots.map((a) => (a.id === d.id && (a.kind === 'rect' || a.kind === 'image') ? { ...a, w: Math.max(6, d.orig.w + (p.x - d.sx)), h: a.kind === 'image' ? Math.max(6, (d.orig.w + (p.x - d.sx)) / d.ar) : Math.max(6, d.orig.h + (p.y - d.sy)) } : a)) } : s));
  };
  const onUp = () => { const d = drag.current; drag.current = null; if (!d) return; setDirty(true); if (d.kind === 'rect') setSnap((s) => { if (!s) return s; const a = s.annots.find((x) => x.id === d.id); return a && a.kind === 'rect' && (a.w < 3 || a.h < 3) ? { ...s, annots: s.annots.filter((x) => x.id !== d.id) } : s; }); bump((n) => n + 1); };
  const startMove = (e: React.PointerEvent, a: Annot) => { if (tool !== 'select') return; e.stopPropagation(); setSel(a.id); const p = pt(e, (e.currentTarget as HTMLElement).closest('[data-overlay]') as HTMLElement); push(); (e.currentTarget as HTMLElement).closest('[data-overlay]')!.setPointerCapture(e.pointerId); drag.current = { kind: 'move', id: a.id, sx: p.x, sy: p.y, orig: a }; };
  const startResize = (e: React.PointerEvent, a: Annot) => { e.stopPropagation(); const p = pt(e, (e.currentTarget as HTMLElement).closest('[data-overlay]') as HTMLElement); push(); (e.currentTarget as HTMLElement).closest('[data-overlay]')!.setPointerCapture(e.pointerId); const o: any = a; drag.current = { kind: 'resize', id: a.id, sx: p.x, sy: p.y, orig: { w: o.w, h: o.h }, ar: o.w / (o.h || 1) }; };
  const patchSel = (p: Partial<Annot>) => setAnnots((l) => l.map((a) => (a.id === sel ? ({ ...a, ...p } as Annot) : a)), false);
  const cur = annots.find((a) => a.id === sel);
  const pageAnnots = annots.filter((a) => a.page === page);

  const pickImage = (f?: File | null, remove = false) => { if (!f) return; const r = new FileReader(); r.onload = () => { const url = String(r.result); const im = new Image(); im.onload = () => { if (remove) { const c = document.createElement('canvas'); c.width = im.naturalWidth; c.height = im.naturalHeight; const x = c.getContext('2d')!; x.drawImage(im, 0, 0); const d = x.getImageData(0, 0, c.width, c.height); for (let i = 0; i < d.data.length; i += 4) if (d.data[i] > 235 && d.data[i + 1] > 235 && d.data[i + 2] > 235) d.data[i + 3] = 0; x.putImageData(d, 0, 0); setImg({ dataUrl: c.toDataURL('image/png'), ar: im.naturalWidth / im.naturalHeight }); } else setImg({ dataUrl: /png|jpe?g/.test(f.type) ? url : '', ar: im.naturalWidth / im.naturalHeight }); setTool('image'); }; im.src = url; }; r.readAsDataURL(f); };

  // ───────── protect / OCR tools ─────────
  const scanPhi = (all: boolean) => guard('Scanning', async () => { if (!pdf) return; const out: (PhiHit & { page: number; on: boolean })[] = []; for (const i of all ? Array.from({ length: pdf.n }, (_, k) => k) : [page]) { const its = await textItems(pdf.pdfjs, pdf.doc, i); for (const h of findPhi(its)) out.push({ ...h, page: i, on: true }); } setPhi(out); if (!out.length) toast.info('No SSNs, phone numbers, e-mails, DOBs or member / account numbers found in the text layer. Scanned pages need OCR first.'); });
  const addRedactions = () => { const on = phi.filter((h) => h.on); if (!on.length) return; setAnnots((l) => [...l, ...on.map((h): Annot => ({ id: newId(), page: h.page, kind: 'rect', x: h.x - 1.5, y: h.y - 1.5, w: h.w + 3, h: h.h + 3, mode: 'redact' }))]); setPhi([]); toast.ok(`${on.length} redaction${on.length > 1 ? 's' : ''} added — review them, then download`); };
  const search = () => guard('Searching', async () => { if (!pdf || q.trim().length < 2) return; const out: (TextHit & { page: number })[] = []; for (let i = 0; i < Math.min(pdf.n, 80); i++) for (const h of findText(await textItems(pdf.pdfjs, pdf.doc, i), q)) out.push({ ...h, page: i }); setHits(out); if (!out.length) toast.info('No matches in the text layer' + (health?.some((h) => h.fix === 'ocr') ? ' — this looks like a scan; run OCR first' : '')); else setPage(out[0].page); });
  const highlightAll = () => { if (!hits.length) return; setAnnots((l) => [...l, ...hits.map((h): Annot => ({ id: newId(), page: h.page, kind: 'rect', x: h.x - 1, y: h.y, w: h.w + 2, h: h.h, mode: 'highlight' }))]); toast.ok(`${hits.length} highlighted`); };
  const claimValues = (): Partial<Record<FieldKey, string>> => { const c = st.claims.find((x) => x.id === claimId); if (!c) return {}; const cl = st.clients.find((x) => x.id === c.client_id); const pv = st.providers.find((x) => x.client_id === c.client_id && x.name.toLowerCase() === (c.provider || '').toLowerCase()); return { claim: c.claim_no, dos: c.dos ? fmtDate(c.dos) : undefined, billed: c.billed_amt ? c.billed_amt.toFixed(2) : undefined, balance: c.balance ? c.balance.toFixed(2) : undefined, payer: c.payer || undefined, provider: c.provider || undefined, npi: pv?.npi || undefined, practice: cl?.name, date: fmtDate(todayISO()), member: c.custom?.member_id ? String(c.custom.member_id) : undefined, auth: c.custom?.auth_no ? String(c.custom.auth_no) : undefined, dx: c.custom?.dx ? String(c.custom.dx) : undefined, cpt: c.cpt || undefined, account: c.account_id || undefined, patient: st.has('view_phi') && c.patient_name ? c.patient_name : undefined }; };
  const scanFill = () => guard('Reading the form', async () => { if (!pdf || !claimId) return; const v = claimValues(); const out: (FillSuggestion & { on: boolean })[] = []; for (let i = 0; i < Math.min(pdf.n, 30); i++) for (const f of suggestFills(await textItems(pdf.pdfjs, pdf.doc, i), v, i)) out.push({ ...f, on: true }); setFills(out); if (!out.length) toast.info('No empty labels it recognises. Fillable PDFs: use the Form tab; scans: run OCR first.'); });
  const applyFills = () => { const on = fills.filter((f) => f.on); if (!on.length) return; setAnnots((l) => [...l, ...on.map((f): Annot => ({ id: newId(), page: f.page, kind: 'text', x: f.x, y: f.y, text: f.value, size: f.size, color: '#0b1f5c', font: 'Helvetica' }))]); setFills([]); toast.ok(`${on.length} field${on.length > 1 ? 's' : ''} filled — check each one, then download`); };
  useEffect(() => { if (!bytes || !pdf) { setHealth(null); return; } let live = true; (async () => { try { const m = await docMeta(bytes); let chars = 0, phi = 0; for (let i = 0; i < Math.min(pdf.n, 30); i++) { const its = await textItems(pdf.pdfjs, pdf.doc, i); chars += its.reduce((a, x) => a + x.str.length, 0); phi += findPhi(its).length; } if (live) setHealth(healthOf(m, { sizeBytes: bytes.length, textChars: chars, phiHits: chars < 40 ? null : phi })); } catch { if (live) setHealth(null); } })(); return () => { live = false; }; }, [bytes, pdf]);
  const runOcr = (onlyScans: boolean) => guard('Running OCR', async () => { if (!snap) return; const baked = await bake(); setOcrProg([0, 1]); const r = await makeSearchable(baked, { onlyScans, onProgress: (d, t) => setOcrProg([d, t]) }); push(); setSnap({ bytes: r.bytes, annots: [] }); setOcrText(r.text); setDirty(true); toast.ok(`OCR added a text layer to ${r.pagesOcr} page${r.pagesOcr === 1 ? '' : 's'} (${r.words} words)${r.pagesSkipped ? `; ${r.pagesSkipped} already had text` : ''}`); }).finally(() => setOcrProg(null));
  const extract = () => guard('Reading text', async () => { if (!pdf) return; let t = ''; for (let i = 0; i < Math.min(pdf.n, 60); i++) { const pg = await pdf.doc.getPage(i + 1); const tc = await pg.getTextContent(); t += tc.items.map((x: any) => x.str + (x.hasEOL ? '\n' : ' ')).join('') + '\n\n'; } setOcrText(t.trim()); if (!t.trim()) toast.info('No text layer — run OCR first'); });

  const T = ({ id, icon, label }: { id: Tool; icon: React.ReactNode; label: string }) => <button className={'btn btn-sm justify-start ' + (tool === id ? 'btn-primary' : '')} title={label} onClick={() => { setTool(id); if (id === 'image' && !img) imgIn.current?.click(); }}>{icon}{label}</button>;

  if (!snap) return (
    <Card><div className="py-10 text-center space-y-4"><FileUp size={30} className="mx-auto muted" /><div className="font-semibold">Open a PDF, or start a new one</div><div className="text-xs muted max-w-md mx-auto">Edit text, redact PHI, sign, stamp, fill forms, reorder pages, merge, split, watermark, number pages, and make scans searchable — all in this browser tab. Nothing is uploaded.</div>
      <div className="flex gap-2 justify-center flex-wrap"><button className="btn btn-primary" onClick={() => fileIn.current?.click()}><FileUp size={14} />Open PDF or image</button><button className="btn" onClick={() => guard('Creating', async () => openBytes('new-document.pdf', await newBlank(1)))}><FilePlus2 size={14} />New blank PDF</button></div>
      <input ref={fileIn} type="file" accept="application/pdf,image/png,image/jpeg,.pdf,.docx,.doc,.xlsx,.xls,.pptx,.ppt,.odt,.ods,.odp,.rtf" hidden onChange={(e) => { void openFile(e.target.files?.[0]); e.target.value = ''; }} /></div></Card>
  );

  return (
    <div className="space-y-3">
      <div className="flex gap-2 flex-wrap items-center panel p-2">
        <button className="btn btn-sm" onClick={() => fileIn.current?.click()}><FileUp size={13} />Open</button><button className="btn btn-sm" onClick={() => guard('Creating', async () => openBytes('new-document.pdf', await newBlank(1)))}><FilePlus2 size={13} />New</button>
        <span className="w-px h-5 bg-white/10" /><button className="btn btn-sm" disabled={!past.current.length} onClick={undo} title="Undo (Ctrl+Z)"><Undo2 size={13} /></button><button className="btn btn-sm" disabled={!future.current.length} onClick={redo} title="Redo (Ctrl+Y)"><Redo2 size={13} /></button>
        <span className="w-px h-5 bg-white/10" /><button className="btn btn-sm" onClick={() => setZoom((z) => Math.max(0.5, +(z - 0.15).toFixed(2)))}><ZoomOut size={13} /></button><span className="text-xs w-10 text-center">{Math.round(zoom * 100)}%</span><button className="btn btn-sm" onClick={() => setZoom((z) => Math.min(3, +(z + 0.15).toFixed(2)))}><ZoomIn size={13} /></button>
        <span className="text-xs muted ml-2">{name}{dirty ? ' •' : ''}</span>
        <div className="ml-auto flex gap-2 items-center">{busy && <Chip color="#6366f1">{busy}…</Chip>}<button className="btn btn-sm" onClick={printIt}><Printer size={13} />Print</button><button className="btn btn-primary btn-sm" onClick={download}><Download size={13} />Download</button>{onExit && <button className="btn btn-ghost btn-sm" onClick={onExit}>Close</button>}</div>
        <input ref={fileIn} type="file" accept="application/pdf,image/png,image/jpeg,.pdf,.docx,.doc,.xlsx,.xls,.pptx,.ppt,.odt,.ods,.odp,.rtf" hidden onChange={(e) => { void openFile(e.target.files?.[0]); e.target.value = ''; }} />
      </div>
      <div className="grid gap-3 lg:grid-cols-[120px_minmax(0,1fr)_300px] items-start">
        <div className="panel p-1.5 max-h-[78vh] overflow-auto space-y-1.5">{pdf && Array.from({ length: Math.min(pdf.n, 80) }, (_, i) => <Thumb key={i + '-' + (bytes?.length || 0)} doc={pdf.doc} index={i} active={i === page} checked={pages.has(i)} onClick={() => setPage(i)} onCheck={() => setPages((s) => { const n = new Set(s); n.has(i) ? n.delete(i) : n.add(i); return n; })} />)}{pdf && pdf.n > 80 && <div className="text-[11px] muted p-1">+{pdf.n - 80} more pages (use the page box)</div>}</div>
        <div className="panel2 p-3 overflow-auto max-h-[78vh]">
          <div className="flex items-center gap-2 mb-2 text-xs"><button className="btn btn-sm" disabled={page <= 0} onClick={() => setPage(page - 1)}>‹</button><span>Page <input type="number" className="input !w-14 !py-0.5 inline" min={1} max={pdf?.n || 1} value={page + 1} onChange={(e) => setPage(Math.max(0, Math.min((pdf?.n || 1) - 1, (+e.target.value || 1) - 1)))} /> of {pdf?.n || '…'}</span><button className="btn btn-sm" disabled={!pdf || page >= pdf.n - 1} onClick={() => setPage(page + 1)}>›</button>{tool !== 'select' && <Chip color="#6366f1">{tool} tool — Esc to stop</Chip>}</div>
          {pdf && <div className="flex justify-center"><PageCanvas doc={pdf.doc} index={page} scale={zoom} onSize={(w, h) => setSize({ w, h })}>
            <div data-overlay className="absolute inset-0" style={{ cursor: tool === 'select' ? 'default' : tool === 'edit' ? 'text' : 'crosshair', touchAction: 'none' }} onPointerDown={onDown} onPointerMove={onMove} onPointerUp={onUp}>
              {tool === 'edit' && items.map((it, i) => <div key={i} className="absolute outline outline-1 outline-sky-400/50 hover:bg-sky-400/20 pointer-events-none" style={{ left: it.x * zoom, top: it.y * zoom, width: it.w * zoom, height: it.h * zoom }} />)}
              {pageAnnots.map((a) => {
                const on = a.id === sel; const ring = on ? 'outline outline-2 outline-brand-500' : ''; const common = { onPointerDown: (e: React.PointerEvent) => startMove(e, a) };
                if (a.kind === 'rect') return <div key={a.id} {...common} className={'absolute ' + ring} style={{ left: a.x * zoom, top: a.y * zoom, width: a.w * zoom, height: a.h * zoom, background: a.mode === 'highlight' ? 'rgba(253,224,71,.45)' : a.mode === 'whiteout' ? '#fff' : a.mode === 'redact' ? 'rgba(0,0,0,.88)' : 'transparent', border: a.mode === 'box' ? '2px solid #dc2626' : a.mode === 'whiteout' && on ? '1px dashed #94a3b8' : undefined, cursor: tool === 'select' ? 'move' : undefined }}>{on && <span className="absolute -right-1.5 -bottom-1.5 w-3 h-3 bg-brand-500 rounded-sm cursor-nwse-resize" onPointerDown={(e) => startResize(e, a)} />}{a.mode === 'redact' && <span className="absolute inset-0 flex items-center justify-center text-[9px] text-white/60 pointer-events-none">REDACT</span>}</div>;
                if (a.kind === 'text') return <div key={a.id} {...common} className={'absolute whitespace-pre-wrap ' + ring} style={{ left: a.x * zoom, top: a.y * zoom, fontSize: a.size * zoom, lineHeight: 1.2, color: a.color, fontFamily: FONT_CSS[a.font], fontWeight: a.bold ? 700 : 400, fontStyle: a.italic ? 'italic' : 'normal', width: a.w ? a.w * zoom : undefined, minWidth: 8, cursor: tool === 'select' ? 'move' : undefined }}>{a.text || ' '}</div>;
                if (a.kind === 'draw') { const xs = a.pts.map((p) => p[0]), ys = a.pts.map((p) => p[1]); return <svg key={a.id} {...common} className={'absolute overflow-visible ' + ring} style={{ left: 0, top: 0, width: size.w * zoom, height: size.h * zoom, pointerEvents: 'none' }}><polyline points={a.pts.map((p) => `${p[0] * zoom},${p[1] * zoom}`).join(' ')} fill="none" stroke={a.color} strokeWidth={a.width * zoom} strokeLinecap="round" strokeLinejoin="round" style={{ pointerEvents: tool === 'select' ? 'stroke' : 'none', cursor: 'move' }} onPointerDown={(e) => startMove(e, a)} />{on && <rect x={Math.min(...xs) * zoom - 3} y={Math.min(...ys) * zoom - 3} width={(Math.max(...xs) - Math.min(...xs)) * zoom + 6} height={(Math.max(...ys) - Math.min(...ys)) * zoom + 6} fill="none" stroke="#6366f1" strokeDasharray="3" />}</svg>; }
                if (a.kind === 'image') return <div key={a.id} {...common} className={'absolute ' + ring} style={{ left: a.x * zoom, top: a.y * zoom, width: a.w * zoom, height: a.h * zoom, cursor: tool === 'select' ? 'move' : undefined }}><img src={a.dataUrl} alt="" draggable={false} className="w-full h-full pointer-events-none" />{on && <span className="absolute -right-1.5 -bottom-1.5 w-3 h-3 bg-brand-500 rounded-sm cursor-nwse-resize" onPointerDown={(e) => startResize(e, a)} />}</div>;
                if (a.kind === 'stamp') return <div key={a.id} {...common} className={'absolute font-bold border-2 px-1.5 ' + ring} style={{ left: a.x * zoom, top: a.y * zoom, fontSize: a.size * zoom, color: a.color, borderColor: a.color, fontFamily: FONT_CSS.Helvetica, cursor: tool === 'select' ? 'move' : undefined }}>{a.text.toUpperCase()}</div>;
                return <div key={a.id} {...common} className={'absolute ' + ring} style={{ left: a.x * zoom, top: a.y * zoom, fontSize: a.size * zoom, color: a.color, lineHeight: 1, cursor: tool === 'select' ? 'move' : undefined }}>✔</div>;
              })}
            </div></PageCanvas></div>}
        </div>

        <div className="space-y-3">
          <div className="seg w-full">{(['edit', 'pages', 'form', 'protect', 'ocr'] as Tab[]).map((t) => <button key={t} className={'flex-1 capitalize ' + (tab === t ? 'on' : '')} onClick={() => setTab(t)}>{t === 'ocr' ? 'OCR' : t}</button>)}</div>
          {tab === 'edit' && <Card title="Edit">
            <div className="grid grid-cols-2 gap-1.5"><T id="select" icon={<MousePointer2 size={13} />} label="Select" /><T id="edit" icon={<TextCursorInput size={13} />} label="Edit text" /><T id="text" icon={<Type size={13} />} label="Add text" /><T id="highlight" icon={<Highlighter size={13} />} label="Highlight" /><T id="whiteout" icon={<Eraser size={13} />} label="Whiteout" /><T id="redact" icon={<EyeOff size={13} />} label="Redact" /><T id="box" icon={<Square size={13} />} label="Box" /><T id="draw" icon={<Pencil size={13} />} label="Draw" /><T id="image" icon={<ImagePlus size={13} />} label="Picture" /><T id="stamp" icon={<Stamp size={13} />} label="Stamp" /><T id="check" icon={<CheckSquare size={13} />} label="Check ✔" /></div>
            <div className="mt-3 space-y-2">
              <div className="grid grid-cols-3 gap-1.5"><select className="input !py-1 text-xs" value={cur?.kind === 'text' ? cur.font : style.font} onChange={(e) => { const f = e.target.value as FontName; setStyle({ ...style, font: f }); if (cur?.kind === 'text') patchSel({ font: f }); }}><option>Helvetica</option><option>Times</option><option>Courier</option></select><input type="number" min={6} max={72} className="input !py-1 text-xs" value={cur?.kind === 'text' || cur?.kind === 'stamp' || cur?.kind === 'check' ? cur.size : style.size} onChange={(e) => { const s = +e.target.value || 12; setStyle({ ...style, size: s }); if (cur && 'size' in cur) patchSel({ size: s } as any); }} /><input type="color" className="input !p-0.5 h-8" value={cur && 'color' in cur && cur.color ? cur.color : style.color} onChange={(e) => { setStyle({ ...style, color: e.target.value }); if (cur && 'color' in cur) patchSel({ color: e.target.value } as any); }} /></div>
              <div className="flex gap-2 text-xs"><label className="flex items-center gap-1"><input type="checkbox" checked={cur?.kind === 'text' ? !!cur.bold : style.bold} onChange={(e) => { setStyle({ ...style, bold: e.target.checked }); if (cur?.kind === 'text') patchSel({ bold: e.target.checked } as any); }} />Bold</label><label className="flex items-center gap-1"><input type="checkbox" checked={cur?.kind === 'text' ? !!cur.italic : style.italic} onChange={(e) => { setStyle({ ...style, italic: e.target.checked }); if (cur?.kind === 'text') patchSel({ italic: e.target.checked } as any); }} />Italic</label></div>
              {tool === 'stamp' && <select className="input !py-1 text-xs" value={stamp} onChange={(e) => setStamp(e.target.value)}>{STAMPS.map((s) => <option key={s}>{s}</option>)}</select>}
              {(tool === 'image' || img) && <div className="text-xs space-y-1"><div className="flex gap-1.5"><button className="btn btn-sm" onClick={() => imgIn.current?.click()}>Choose picture</button><label className="btn btn-sm cursor-pointer" title="Make white pixels transparent — good for scanned signatures">Signature scan<input type="file" accept="image/png,image/jpeg" hidden onChange={(e) => { pickImage(e.target.files?.[0], true); e.target.value = ''; }} /></label></div>{img && <img src={img.dataUrl} alt="" className="h-10 bg-white rounded" />}</div>}
              <input ref={imgIn} type="file" accept="image/png,image/jpeg" hidden onChange={(e) => { pickImage(e.target.files?.[0]); e.target.value = ''; }} />
              {cur?.kind === 'text' && <textarea className="input text-xs" rows={3} value={cur.text} onChange={(e) => patchSel({ text: e.target.value } as any)} />}
              {cur && <div className="flex gap-1.5"><button className="btn btn-sm" onClick={() => { const c = { ...cur, id: newId() } as any; if ('x' in c) { c.x += 12; c.y += 12; } setAnnots((l) => [...l, c]); setSel(c.id); }}><Copy size={12} />Duplicate</button><button className="btn btn-sm" onClick={() => { setAnnots((l) => l.filter((a) => a.id !== sel)); setSel(null); }}><Trash2 size={12} />Delete</button></div>}
              <p className="text-[11px] muted">Edit text: click a line of existing text — it is whited out and replaced with an editable box in the same spot and size. Drag to move; handles resize. Esc stops a tool.</p>
              <div className="border-t hair pt-2 space-y-1.5"><div className="label">Find in document</div><div className="flex gap-1.5"><input className="input !py-1 text-xs" value={q} onChange={(e) => setQ(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && search()} placeholder="Claim #, name, code…" /><button className="btn btn-sm" onClick={search}>Find</button></div>
              {hits.length > 0 && <><div className="flex items-center gap-1.5 text-[11px]"><span>{hits.length} match{hits.length > 1 ? 'es' : ''}</span><button className="btn btn-sm" onClick={highlightAll}><Highlighter size={12} />Highlight all</button></div><div className="max-h-28 overflow-auto text-[11px] space-y-0.5">{hits.slice(0, 40).map((h, i) => <button key={i} className="block w-full text-left truncate hover:bg-white/5 rounded px-1" onClick={() => setPage(h.page)}><b>p{h.page + 1}</b> {h.context}</button>)}</div></>}</div>
            <details className="border-t hair pt-2"><summary className="text-xs font-semibold cursor-pointer">Signature &amp; initials</summary><div className="mt-1.5"><SigPad onUse={(d, ar) => { setImg({ dataUrl: d, ar }); setTool('image'); toast.info('Click on the page to place it'); }} /></div></details>
            <details className="border-t hair pt-2"><summary className="text-xs font-semibold cursor-pointer">Fill from a claim</summary><div className="mt-1.5 space-y-1.5 text-xs"><p className="muted">Finds empty labels on a flat form (Claim #, Date of service, Member ID, NPI…) and types the claim’s data beside them. Patient name is filled only if your role may see it.</p><select className="input !py-1 text-xs" value={claimId} onChange={(e) => { setClaimId(e.target.value); setFills([]); }}><option value="">Choose a claim…</option>{st.claims.filter((c) => st.inScope(c.client_id)).slice(0, 1500).map((c) => <option key={c.id} value={c.id}>{c.claim_no} · {c.payer}</option>)}</select><button className="btn btn-sm" disabled={!claimId} onClick={scanFill}><Wand2 size={12} />Find fields</button>
              {fills.length > 0 && <><div className="max-h-32 overflow-auto space-y-0.5">{fills.map((f, i) => <label key={i} className="flex items-center gap-1.5"><input type="checkbox" checked={f.on} onChange={() => setFills((l) => l.map((x, j) => (j === i ? { ...x, on: !x.on } : x)))} /><span className="muted">p{f.page + 1} {f.label}</span><b className="truncate">{f.value}</b></label>)}</div><button className="btn btn-primary btn-sm" onClick={applyFills}>Fill {fills.filter((f) => f.on).length} field(s)</button></>}</div></details>
              <div className="text-[11px] muted">{pageAnnots.length} change{pageAnnots.length === 1 ? '' : 's'} on this page · {annots.length} total</div>
            </div>
          </Card>}

          {tab === 'pages' && <Card title={`Pages — ${pages.size ? pages.size + ' selected' : 'current page'}`}>
            <div className="grid grid-cols-2 gap-1.5">
              <button className="btn btn-sm" onClick={() => structural('Rotating', (b) => rotatePages(b, idxs(), 90))}><RotateCw size={13} />Rotate right</button><button className="btn btn-sm" onClick={() => structural('Rotating', (b) => rotatePages(b, idxs(), -90))}><RotateCcw size={13} />Rotate left</button>
              <button className="btn btn-sm" onClick={() => structural('Deleting', (b) => deletePages(b, idxs()))}><Trash2 size={13} />Delete</button><button className="btn btn-sm" onClick={() => structural('Duplicating', (b) => duplicatePage(b, idxs()[0]))}><Copy size={13} />Duplicate</button>
              <button className="btn btn-sm" disabled={page <= 0} onClick={async () => { await structural('Moving', (b) => movePage(b, page, page - 1)); setPage(page - 1); }}><ArrowUp size={13} />Move up</button><button className="btn btn-sm" disabled={!pdf || page >= pdf.n - 1} onClick={async () => { await structural('Moving', (b) => movePage(b, page, page + 1)); setPage(page + 1); }}><ArrowDown size={13} />Move down</button>
              <button className="btn btn-sm" onClick={() => structural('Inserting', (b) => insertBlank(b, page + 1))}><FilePlus2 size={13} />Blank after</button><button className="btn btn-sm" onClick={() => guard('Extracting', async () => { const out = await extractPages(await bake(), idxs()); downloadFile(name.replace(/\.pdf$/i, '') + '-pages.pdf', blob(out), 'application/pdf'); })}><Scissors size={13} />Extract</button>
            </div>
            <div className="mt-3 space-y-2 text-xs"><div className="label">Merge</div><div className="flex gap-1.5"><button className="btn btn-sm" onClick={() => mergeIn.current?.click()}><Combine size={13} />Add PDF at end</button><button className="btn btn-sm" onClick={() => imgPageIn.current?.click()}><ImagePlus size={13} />Add images</button></div>
              <input ref={mergeIn} type="file" accept="application/pdf" hidden onChange={(e) => { const f = e.target.files?.[0]; e.target.value = ''; if (f) void structural('Merging', async (b) => mergePdfs([b, new Uint8Array(await f.arrayBuffer())])); }} />
              <input ref={imgPageIn} type="file" multiple accept="image/png,image/jpeg" hidden onChange={(e) => { const fl = [...(e.target.files || [])]; e.target.value = ''; if (fl.length) void structural('Adding images', async (b) => mergePdfs([b, await imagesToPdf(await Promise.all(fl.map(async (f) => ({ bytes: new Uint8Array(await f.arrayBuffer()), type: f.type }))))])); }} />
              <div className="label pt-1">Split into files</div><div className="flex gap-1.5"><input className="input !py-1" value={split} onChange={(e) => setSplit(e.target.value)} placeholder="1-3, 4-6, 7-" /><button className="btn btn-sm" onClick={() => guard('Splitting', async () => { const parts = await splitRanges(await bake(), split); parts.forEach((p, i) => downloadFile(`${name.replace(/\.pdf$/i, '')}-part${i + 1}.pdf`, blob(p), 'application/pdf')); toast.ok(`${parts.length} files saved`); })}>Split</button></div></div>
          </Card>}

          {tab === 'form' && <Card title="Form fields">{fields.length === 0 ? <div className="text-xs muted">This PDF has no fillable fields. Use <b>Add text</b> to type onto a flat form, or <b>✔ Check</b> to tick boxes.</div> : <div className="space-y-2 max-h-96 overflow-auto pr-1">{fields.map((f) => <Field key={f.name} label={f.name}>{f.type === 'check' ? <select className="input !py-1" value={vals[f.name] || ''} onChange={(e) => setVals({ ...vals, [f.name]: e.target.value })}><option value="">—</option><option value="yes">Checked</option><option value="no">Unchecked</option></select> : <input className="input !py-1" value={vals[f.name] || ''} onChange={(e) => setVals({ ...vals, [f.name]: e.target.value })} />}</Field>)}<div className="flex gap-1.5"><button className="btn btn-primary btn-sm" onClick={() => structural('Filling', (b) => fillPdf(b, { fields: Object.fromEntries(Object.entries(vals).filter(([, v]) => v !== '')) }))}>Fill fields</button><button className="btn btn-sm" onClick={() => structural('Flattening', (b) => fillPdf(b, { fields: Object.fromEntries(Object.entries(vals).filter(([, v]) => v !== '')), flatten: true }))}>Fill &amp; flatten</button></div></div>}</Card>}

          {tab === 'protect' && <>
            <Card title="Document health">{!health ? <div className="text-xs muted">Checking…</div> : <div className="space-y-1.5 text-xs">{health.map((h, i) => <div key={i} className="flex gap-1.5 items-start"><span style={{ color: h.level === 'ok' ? '#16a34a' : h.level === 'warn' ? '#d97706' : '#dc2626' }}>{h.level === 'ok' ? '✔' : '●'}</span><span className="flex-1">{h.text}</span>{h.fix && <button className="btn btn-sm" onClick={() => { if (h.fix === 'ocr') setTab('ocr'); else if (h.fix === 'scrub') void structural('Cleaning', scrubMetadata); else if (h.fix === 'phi') void scanPhi(true); else void structural('Optimizing', optimize); }}>{h.fix === 'ocr' ? 'OCR' : h.fix === 'scrub' ? 'Remove' : h.fix === 'phi' ? 'Review' : 'Shrink'}</button>}</div>)}</div>}</Card>
            <Card title="Redact PHI"><div className="text-xs space-y-2"><p className="muted">Finds SSNs, phone numbers, e-mails, dates of birth and member / account numbers in the text layer and proposes black-box redactions. Redacted pages are flattened to images when you download, so the hidden text is really gone.</p><div className="flex gap-1.5"><button className="btn btn-sm" onClick={() => scanPhi(false)}><ShieldAlert size={13} />Scan this page</button><button className="btn btn-sm" onClick={() => scanPhi(true)}>Scan all pages</button></div>
              {phi.length > 0 && <><div className="max-h-40 overflow-auto space-y-0.5">{phi.map((h, i) => <label key={i} className="flex items-center gap-1.5"><input type="checkbox" checked={h.on} onChange={() => setPhi((l) => l.map((x, j) => (j === i ? { ...x, on: !x.on } : x)))} /><Chip color="#dc2626">{h.kind}</Chip><span className="truncate">{h.text}</span><span className="muted ml-auto">p{h.page + 1}</span></label>)}</div><button className="btn btn-primary btn-sm" onClick={addRedactions}><EyeOff size={13} />Redact {phi.filter((h) => h.on).length} selected</button></>}</div></Card>
            <Card title="Watermark &amp; numbering"><div className="text-xs space-y-2"><div className="flex gap-1.5"><input className="input !py-1" value={mark.text} onChange={(e) => setMark({ ...mark, text: e.target.value })} /><button className="btn btn-sm" onClick={() => structural('Watermarking', (b) => watermark(b, { text: mark.text, opacity: mark.opacity }))}><Droplet size={13} />Add</button></div>
              <div className="grid grid-cols-2 gap-1.5"><input className="input !py-1" value={num.template} onChange={(e) => setNum({ ...num, template: e.target.value })} title="{n} page · {N} total · {bates} Bates number" /><select className="input !py-1" value={num.pos} onChange={(e) => setNum({ ...num, pos: e.target.value as Pos })}><option value="bc">Bottom centre</option><option value="br">Bottom right</option><option value="bl">Bottom left</option><option value="tc">Top centre</option><option value="tr">Top right</option><option value="tl">Top left</option></select><input className="input !py-1" placeholder="Bates prefix e.g. ACME-" value={num.prefix} onChange={(e) => setNum({ ...num, prefix: e.target.value })} /><input type="number" className="input !py-1" value={num.start} onChange={(e) => setNum({ ...num, start: +e.target.value || 1 })} /></div>
              <div className="flex gap-1.5 flex-wrap"><button className="btn btn-sm" onClick={() => structural('Numbering', (b) => numberPages(b, { template: num.template, pos: num.pos, start: num.start }))}><Hash size={13} />Page numbers</button><button className="btn btn-sm" onClick={() => structural('Bates', (b) => numberPages(b, { template: '{bates}', prefix: num.prefix, start: num.start, pos: num.pos }))}>Bates numbers</button></div></div></Card>
            {(svc.up('stirling') || svc.up('gotenberg')) && <Card title="Local server tools"><div className="text-xs space-y-2"><p className="muted">Run by the document services on your own server — nothing leaves it.</p>{svc.up('stirling') && <div className="flex gap-1.5 flex-wrap items-center"><button className="btn btn-sm" onClick={() => structural('Compressing on the server', (b) => compressPdf(b, 6))}>Compress (server)</button><button className="btn btn-sm" onClick={() => structural('OCR on the server', ocrPdfOnServer)}>OCR whole file (server)</button></div>}</div></Card>}
            <Card title="Clean up"><div className="flex gap-1.5 flex-wrap text-xs"><button className="btn btn-sm" onClick={() => structural('Cleaning', scrubMetadata)}><Wand2 size={13} />Remove metadata</button><button className="btn btn-sm" onClick={() => structural('Optimizing', optimize)}>Optimize size</button></div><p className="text-[11px] muted mt-2">Metadata can carry author, practice or patient names from the program that made the file.</p></Card></>}

          {tab === 'ocr' && <Card title="OCR &amp; text"><div className="text-xs space-y-2"><p className="muted">Runs in this tab with the self-hosted engine — nothing is uploaded. It adds an invisible text layer so scans become searchable and copyable, and the Document OCR page can read them.</p>
            <div className="flex gap-1.5 flex-wrap"><button className="btn btn-primary btn-sm" disabled={!!ocrProg} onClick={() => runOcr(true)}><ScanText size={13} />Make scans searchable</button><button className="btn btn-sm" disabled={!!ocrProg} onClick={() => runOcr(false)}>OCR every page</button>{svc.up('stirling') && <button className="btn btn-sm" disabled={!!busy} title="Runs on your local document server — no page limit" onClick={() => structural('OCR on the server', ocrPdfOnServer)}>OCR on server (any size)</button>}<button className="btn btn-sm" onClick={extract}>Show text</button></div>
            {ocrProg && <div className="space-y-1"><div className="h-1.5 rounded bg-white/10"><div className="h-1.5 rounded bg-brand-500" style={{ width: `${Math.round((ocrProg[0] / Math.max(1, ocrProg[1])) * 100)}%` }} /></div><div>Page {Math.min(ocrProg[0] + 1, ocrProg[1])} of {ocrProg[1]}…</div></div>}
            {ocrText && <><textarea className="input font-mono text-[11px]" rows={8} readOnly value={ocrText} /><div className="flex gap-1.5 flex-wrap"><button className="btn btn-sm" onClick={() => { void navigator.clipboard.writeText(ocrText); toast.ok('Copied'); }}>Copy</button><button className="btn btn-primary btn-sm" onClick={() => { putInbox({ kind: 'text', name, text: ocrText }); nav('/ocr'); }}>Analyze in Document OCR</button>{onToWord && <button className="btn btn-sm" onClick={() => onToWord(name.replace(/\.pdf$/i, '') + '.docx', ocrText)}>Edit text in Word</button>}</div></>}</div></Card>}
        </div>
      </div>
    </div>
  );
}
